import { abilityModifier, type Ability } from './core.ts';
import type { Effect, GameClock } from './effects.ts';
import { checkRequirements, type AbilityScores, type Requirement } from './requirements.ts';

// ARMOUR -----------------------------------------------------------------

export type ArmorCategory = 'light' | 'medium' | 'heavy' | 'shield';

/** How the Dexterity modifier counts toward armour class, by category (SRD Armor table). */
export const ARMOR_CATEGORY_RULES: Record<
  Exclude<ArmorCategory, 'shield'>,
  { addsDex: boolean; dexMax: number | null }
> = {
  // "11 + Dex modifier"
  light: { addsDex: true, dexMax: null },
  // "12 + Dex modifier (max 2)"
  medium: { addsDex: true, dexMax: 2 },
  // "16": no Dexterity at all
  heavy: { addsDex: false, dexMax: null },
};

/** Armour or a shield, as the SRD lists it. For a shield, baseAc is the bonus it adds (+2). */
export interface ArmorDef {
  id: string;
  name: string;
  category: ArmorCategory;
  baseAc: number;
  /** The Strength score below which the wearer's speed drops by 10 feet; null when there is none. */
  strength: number | null;
  /** Disadvantage on Dexterity (Stealth) checks while worn. */
  stealthDisadvantage: boolean;
}

export interface ArmorClassInput {
  /** Body armour, or null for none. */
  armor: ArmorDef | null;
  shield?: ArmorDef | null;
  abilityScores: AbilityScores;
  /** Effects can lift Strength over an armour's requirement (the requirement is checked with them). */
  effects?: readonly Effect[];
  clock?: GameClock;
  /** Training with the armour's category (and with shields). Default true. */
  trained?: boolean;
  trainedWithShield?: boolean;
}

export interface ArmorClassResult {
  value: number;
  parts: { label: string; value: number }[];
  /** Feet of speed lost to armour that is too heavy for the wearer's Strength. */
  speedPenaltyFt: number;
  stealthDisadvantage: boolean;
  notes: string[];
}

/** The unarmoured base: 10 + Dexterity modifier. */
export const UNARMORED_BASE_AC = 10;
/** Feet of speed lost when the wearer's Strength is below the armour's Strength score. */
export const ARMOR_SPEED_PENALTY_FT = 10;

/** The Strength score of a suit of armour as a P1-3 requirement: met, or 10 feet less speed. */
export function armorRequirements(armor: ArmorDef): Requirement[] {
  return armor.strength === null
    ? []
    : [{ stat: 'str', min: armor.strength, onUnmet: 'speed_penalty', penaltyFt: ARMOR_SPEED_PENALTY_FT }];
}

/** Armour class from armour, shield and Dexterity, with the speed penalty and stealth note armour brings. */
export function armorClass({
  armor,
  shield = null,
  abilityScores,
  effects = [],
  clock = { seconds: 0 },
  trained = true,
  trainedWithShield = true,
}: ArmorClassInput): ArmorClassResult {
  if (armor?.category === 'shield') throw new RangeError(`${armor.name} is a shield, not body armour`);
  if (shield && shield.category !== 'shield') throw new RangeError(`${shield.name} is not a shield`);
  const dex = abilityModifier(abilityScores.dex);
  const parts: { label: string; value: number }[] = [];
  const notes: string[] = [];

  if (!armor) {
    parts.push({ label: 'Unarmoured', value: UNARMORED_BASE_AC }, { label: 'Dexterity', value: dex });
  } else {
    parts.push({ label: armor.name, value: armor.baseAc });
    const rule = ARMOR_CATEGORY_RULES[armor.category];
    if (rule.addsDex) {
      parts.push({ label: 'Dexterity', value: rule.dexMax === null ? dex : Math.min(dex, rule.dexMax) });
    }
  }
  // the shield's bonus counts only with training
  if (shield && trainedWithShield) parts.push({ label: shield.name, value: shield.baseAc });
  if (shield && !trainedWithShield) notes.push(`No training with shields: the ${shield.name} adds nothing`);

  let speedPenaltyFt = 0;
  if (armor) {
    const check = checkRequirements(
      { id: armor.id, name: armor.name, requirements: armorRequirements(armor) },
      abilityScores,
      effects,
      clock,
    );
    speedPenaltyFt = check.speedPenaltyFt;
    if (speedPenaltyFt) {
      notes.push(`${armor.name} needs Strength ${armor.strength}: speed is ${speedPenaltyFt} feet lower`);
    }
    if (!trained) {
      notes.push(
        `No training with ${armor.category} armour: disadvantage on Strength and Dexterity rolls, and no spells`,
      );
    }
  }
  const stealthDisadvantage = !!armor?.stealthDisadvantage;
  if (stealthDisadvantage) notes.push(`${armor!.name}: disadvantage on Dexterity (Stealth) checks`);

  return { value: parts.reduce((sum, p) => sum + p.value, 0), parts, speedPenaltyFt, stealthDisadvantage, notes };
}

// WEAPONS ----------------------------------------------------------------

export type WeaponProperty =
  'ammunition' | 'finesse' | 'heavy' | 'light' | 'loading' | 'reach' | 'thrown' | 'two-handed' | 'versatile';

export type WeaponMastery = 'cleave' | 'graze' | 'nick' | 'push' | 'sap' | 'slow' | 'topple' | 'vex';

export interface WeaponDef {
  id: string;
  name: string;
  category: 'simple' | 'martial';
  kind: 'melee' | 'ranged';
  /** e.g. { dice: '1d8', type: 'slashing' }; a flat number such as '1' for the Blowgun. */
  damage: { dice: string; type: string };
  properties: WeaponProperty[];
  /** The two-handed damage of a Versatile weapon, e.g. '1d10'. */
  versatileDice?: string;
  /** Normal and long range in feet, for Ammunition and Thrown weapons. */
  range?: { normal: number; long: number };
  /** The ammunition it fires, e.g. 'arrow'. */
  ammunition?: string;
  mastery: WeaponMastery;
}

export interface WeaponProfile {
  /** The ability for attack and damage rolls. */
  ability: Ability;
  modifier: number;
  /** The damage dice as held (versatile weapons do more in two hands). */
  damageDice: string;
  damageType: string;
  twoHanded: boolean;
  /** Melee reach in feet; null for a ranged weapon. */
  reachFt: number | null;
  /** Normal and long range, for ranged and thrown attacks. */
  range: { normal: number; long: number } | null;
  mastery: WeaponMastery;
  /** Reasons for disadvantage, ready for resolveRollMode (a Heavy weapon without the score for it). */
  disadvantage: string[];
  notes: string[];
}

/** A Heavy melee weapon wants Strength 13, a Heavy ranged weapon Dexterity 13. */
export const HEAVY_WEAPON_MIN_SCORE = 13;
export const REACH_FT = 5;

const has = (w: WeaponDef, p: WeaponProperty) => w.properties.includes(p);

/**
 * What a weapon does in a character's hands. Finesse uses the better of Strength and Dexterity; other ranged
 * weapons use Dexterity; other melee weapons use Strength, thrown or not.
 */
export function weaponProfile(
  weapon: WeaponDef,
  abilityScores: AbilityScores,
  options: { twoHanded?: boolean } = {},
): WeaponProfile {
  const str = abilityModifier(abilityScores.str);
  const dex = abilityModifier(abilityScores.dex);
  const ability: Ability = has(weapon, 'finesse')
    ? dex > str
      ? 'dex'
      : 'str'
    : weapon.kind === 'ranged'
      ? 'dex'
      : 'str';

  const versatileInTwoHands = has(weapon, 'versatile') && !!options.twoHanded && weapon.kind === 'melee';
  if (has(weapon, 'versatile') && !weapon.versatileDice) {
    throw new RangeError(`${weapon.name} is Versatile but has no two-handed damage`);
  }
  const twoHanded = has(weapon, 'two-handed') || versatileInTwoHands;

  const disadvantage: string[] = [];
  if (has(weapon, 'heavy')) {
    const [stat, label] = weapon.kind === 'melee' ? (['str', 'Strength'] as const) : (['dex', 'Dexterity'] as const);
    if (abilityScores[stat] < HEAVY_WEAPON_MIN_SCORE) {
      disadvantage.push(`Heavy: ${weapon.name} needs ${label} ${HEAVY_WEAPON_MIN_SCORE}`);
    }
  }
  const notes: string[] = [];
  if (has(weapon, 'loading')) notes.push('Loading: one shot per action, bonus action or reaction');
  if (has(weapon, 'ammunition') && weapon.ammunition) notes.push(`Needs ammunition: ${weapon.ammunition}`);
  if (has(weapon, 'thrown') && weapon.kind === 'melee') notes.push('Can be thrown');

  return {
    ability,
    modifier: ability === 'dex' ? dex : str,
    damageDice: versatileInTwoHands ? weapon.versatileDice! : weapon.damage.dice,
    damageType: weapon.damage.type,
    twoHanded,
    reachFt: weapon.kind === 'melee' ? REACH_FT + (has(weapon, 'reach') ? 5 : 0) : null,
    range: weapon.range ?? null,
    mastery: weapon.mastery,
    disadvantage,
    notes,
  };
}
